                    "sql": "Create or replace table MapleMonk.zouk_MARKETING_CONSOLIDATED_DTC as select * from MapleMonk.zouk_MARKETING_CONSOLIDATED where lower(Channel) like any (\'%facebook%\',\'%google%\',\'%contlo%\',\'%bitespeed%\') ; Create or replace table MapleMonk.zouk_MARKETING_CONSOLIDATED_MP as select * from MapleMonk.zouk_MARKETING_CONSOLIDATED where not(lower(Channel) like any (\'%facebook%\',\'%google%\',\'%contlo%\',\'%bitespeed%\')) ; Create or replace table Maplemonk.zouk_new_initiative_MP AS select * from `MapleMonk.zouk_MARKETING_CONSOLIDATED` where CAMPAIGN_ID like \'120229486049350758\' ; Create or replace table maplemonk.zouk_sales_consolidated_DTC as select * from maplemonk.zouk_sales_consolidated where not(lower(MARKETPLACE_SEGMENT) like any (\'%commerce%\',\'%offline%\')) ; Create or replace table `MapleMonk.Zouk_Product_Sales_Cost_Source_DTC` as select * from MapleMonk.Zouk_Product_Sales_Cost_Source where (lower(MARKETPLACE) like any (\'shopify\',\'shopify web\',\'shopify app\', \'shopify ios app\',\'shopify android app\')) ; Create or replace table `MapleMonk.Zouk_Product_Seconday_Sales_Cost_Source_MP` as select * from MapleMonk.Zouk_Product_Secondary_Sales_Cost_Source where (lower(MARKETPLACE_SEGMENT) like any (\'%commerce%\')) ; Create or replace table maplemonk.zouk_sales_consolidated_DTC as select * from maplemonk.zouk_sales_consolidated where not(lower(MARKETPLACE_SEGMENT) like any (\'%commerce%\',\'%offline%\')) ; Create or replace table maplemonk.zouk_sales_cost_source_DTC as select * from maplemonk.zouk_sales_cost_source where lower(Marketplace) like any (\'%shopify%\',\'%website%\',\'app\') ; Create or replace table maplemonk.zouk_sales_cost_source_MP as select * from maplemonk.zouk_sales_cost_source where not(lower(Marketplace) like any (\'%shopify%\',\'%website%\',\'app\',\'%offline%\',\'%ebo%\')) ; Create or replace table maplemonk.zouk_sales_consolidated_MP as select * from maplemonk.zouk_sales_consolidated where lower(MARKETPLACE_SEGMENT) like \'%commerce%\' ; create or replace table `MapleMonk.zouk_Mens_collection_Secondary_Sales` as select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(COLLECTION) like \'%men%\' ; Create or replace table maplemonk.zouk_sales_consolidated_offline as WITH Sessions AS ( SELECT DATE(SAFE_CAST(time AS DATETIME)) AS Date, UPPER(m.store_name) AS Store, \"SHOPIFY POS\" AS marketplace, 0 AS Walkins, sum(SAFE_CAST(passengerFlow AS INT64)) AS Footfall FROM `MapleMonk.zouk_get_many_shops_passenger_indicator_data` d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_id)) = TRIM(LOWER(m.store_id)) GROUP BY 1,2 UNION ALL SELECT PARSE_DATE(\'%Y-%m-%d\', d.Date) AS Date, UPPER(m.store_name) AS Store, \"SHOPIFY POS\" AS marketplace, 0 AS Walkins, SUM(SAFE_CAST(d.total_count AS INT64)) AS Footfall FROM ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY Date, store_code ORDER BY Date DESC ) AS rn FROM `MapleMonk.Zouk_ext_analytics` ) WHERE rn = 1 ) d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_code)) = TRIM(LOWER(m.store_id)) GROUP BY 1, 2 UNION ALL SELECT PARSE_DATE(\'%Y-%m-%d\', date_string) AS Date, UPPER(m.store_name) AS Store, \"SHOPIFY POS\" AS marketplace, SAFE_CAST(engagers_group_count AS INT64) AS Walkins, SAFE_CAST(engagers_count AS INT64) AS Footfall FROM `MapleMonk.zouk_db_get_consolidated_day` d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_id)) = TRIM(LOWER(m.store_id)) ), Footfall AS ( SELECT Date,Store,sum(footfall) AS Footfall FROM Sessions Group By 1,2 ) select s.*, m.City as Store_City, m.Tier, m.State as Store_State, m.Region, m.Store_Type, m.City_Cluster, m.Store_Classification, CASE WHEN ROW_NUMBER() OVER(PARTITION BY s.Order_Date, s.SOURCE ORDER BY s.Order_ID) = 1 THEN f.Footfall ELSE 0 END AS Footfall from maplemonk.zouk_sales_consolidated s left join `MapleMonk.Zouk_EBO_Store_Master` m on UPPER(s.Store_Code) = UPPER(m.Store_Code) AND lower(s.source) = lower(m.Store_Name) left join footfall f ON s.Order_Date = f.Date AND trim(lower(s.SOURCE)) = trim(lower(f.Store)) where (lower(MARKETPLACE_SEGMENT) like any (\'%offline%\',\'%ebo%\')) ; Create or replace table maplemonk.zouk_secondary_sales_consolidated_MP as select * from maplemonk.zouk_secondary_sales_consolidated where lower(MARKETPLACE_SEGMENT) like \'%commerce%\' ; Create or replace table maplemonk.zouk_pandl_offline as WITH Sessions AS ( SELECT DATE(SAFE_CAST(time AS DATETIME)) AS Date, UPPER(m.store_name) AS Store, \"SHOPIFY POS\" AS marketplace, sum(SAFE_CAST(passengerFlow AS INT64)) AS Footfall FROM `MapleMonk.zouk_get_many_shops_passenger_indicator_data` d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_id)) = TRIM(LOWER(m.store_id)) GROUP BY 1,2 UNION ALL SELECT PARSE_DATE(\'%Y-%m-%d\', d.Date) AS Date, UPPER(m.store_name) AS Store, \"SHOPIFY POS\" AS marketplace, SUM(SAFE_CAST(d.total_count AS INT64)) AS Footfall FROM ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY Date, store_code ORDER BY Date DESC ) AS rn FROM `MapleMonk.Zouk_ext_analytics` ) WHERE rn = 1 ) d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_code)) = TRIM(LOWER(m.store_id)) GROUP BY 1, 2 UNION ALL SELECT PARSE_DATE(\'%Y-%m-%d\', date_string) AS Date, UPPER(m.store_name) AS Store, \"SHOPIFY POS\" AS marketplace, SAFE_CAST(engagers_count AS INT64) AS Footfall FROM `MapleMonk.zouk_db_get_consolidated_day` d LEFT JOIN `Maplemonk.zouk_ebo_Mapping_sheet` m ON TRIM(LOWER(d.store_id)) = TRIM(LOWER(m.store_id)) ), Footfall AS ( SELECT Date,Store,sum(footfall) AS Footfall FROM Sessions Group By 1,2 ) select p.*, e.Store_Code, CASE WHEN ROW_NUMBER() OVER( PARTITION BY DATE_TRUNC(p.Date, MONTH), trim(lower(p.SOURCE)) ORDER BY p.Date ASC, p.REFERENCE_CODE ASC ) = 1 THEN CAST(e.Carpet_Area AS INT64) ELSE 0 END AS Carpet_Area, CASE WHEN ROW_NUMBER() OVER(PARTITION BY p.Date, p.SOURCE ORDER BY p.REFERENCE_CODE) = 1 THEN f.Footfall ELSE 0 END AS Footfall from maplemonk.zouk_pandl p left join footfall f ON p.Date = f.Date AND trim(lower(p.SOURCE)) = trim(lower(f.Store)) LEFT JOIN `MapleMonk.Zouk_Offline_EBO_Store_Master` e ON trim(lower(p.source)) = trim(lower(e.Store_Name)) where lower(final_Marketplace) like any (\'%offline%\',\'ebo\') ; Create or replace table maplemonk.zouk_pandl_DTC as select * from maplemonk.zouk_pandl where (lower(final_Marketplace) like any (\'%shopify%\',\'%website%\',\'app\')) ; Create or replace table maplemonk.zouk_pandl_MP as select * from maplemonk.zouk_pandl where not(lower(final_Marketplace) like any (\'%shopify%\',\'%website%\',\'app\',\'%offline%\',\'ebo\')) ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Power_Potli_Data AS select * from `MapleMonk.zouk_Secondary_sales_consolidated` where lower(PRODUCT_CATEGORY) like \'%power%\' ; CREATE OR REPLACE TABLE MapleMonk.zouk_Luggage_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(COLLECTION) like any (\'%luggage%\',\'%duffle%\') ; CREATE OR REPLACE TABLE MapleMonk.zouk_Mens_Collection_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE LOWER(COLLECTION) like \"men\'s collection\" ; CREATE OR REPLACE TABLE MapleMonk.zouk_Backpack_Secondary_PandL AS SELECT * FROM `MapleMonk.zouk_secondary_pandl` WHERE UPPER(PRODUCT_CATEGORY) LIKE ANY (\"CLASSIC BACKPACK\", \"STATEMENT BACKPACK\", \"OLINA DAYPACK\", \"DOME DAYPACK\", \"AMALIA DAYPACK\", \"AMALIA BACKPACK (LARGE)\", \"TAARAN BACKPACK\", \"CONSULTANT BACKPACK\", \"MAYRA MINI-DAYPACK\", \"DALILA MINI-DAYPACK\", \"CLASSIC DAYPACK\", \"LAPTOP BACKPACK\", \"OFFICE BACKPACK\") ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Secondary_Sales_Consolidated_MT AS select * from `MapleMonk.zouk_Secondary_sales_consolidated` WHERE lower(FINAL_MARKETPLACE) like \'%offline_mt%\' ; CREATE OR REPLACE TABLE MapleMonk.Zouk_Lineitem_Pricing_Report AS SELECT NAME, Date(safe_cast(created_at as datetime)) As Created_At, JSON_EXTRACT_SCALAR(line_item_json, \'$.title\') AS LineItem_Name, JSON_EXTRACT_SCALAR(line_item_json, \'$.sku\') AS LineItem_SKU, CAST(JSON_EXTRACT_SCALAR(line_item_json, \'$.price\') AS FLOAT64) AS LineItem_Price, CAST(JSON_EXTRACT_SCALAR(line_item_json, \'$.quantity\') AS INT64) AS LineItem_Quantity FROM `zouk-wh.maplemonk.Shopify_zoukbags_ORDERS`, UNNEST(line_items) AS line_item_json ; CREATE OR REPLACE TABLE `MapleMonk.Zouk_Footfall_Analysis` AS SELECT SAFE_CAST(time AS datetime) AS Date_time, DATE(SAFE_CAST(time AS datetime)) AS Date, p.store_id, m.store_name, SAFE_CAST(p.passengerFlow AS FLOAT64) as Foot_fall FROM MapleMonk.Zouk_get_many_shops_passenger_indicator_data p LEFT JOIN MapleMonk.Zouk_EBO_Mapping_Sheet AS m ON trim(p.store_id) = trim(m.store_id) ;",
